// Regular-cell lookup data from Eric Lengyel's Transvoxel reference implementation.
// Source commit: 51a494f03c5b024cd153b596bcc7152eb3cc93a6
// https://github.com/EricLengyel/Transvoxel
// Licensed under the MIT License; see Archive/ThirdParty/Transvoxel-LICENSE.txt.
internal static class VoxelTransvoxelTables
{
	private const string RegularCellClassBase64 = "";
	private const string RegularGeometryCountsBase64 = "ADFiQlNzk4SExGRkZGR1lQ==";
	private const string RegularTriangleIndicesBase64 = "";
	private const string RegularVertexDataBase64 = "";

	public static readonly byte[] RegularCellClass = System.Convert.FromBase64String( RegularCellClassBase64 );
	public static readonly byte[] RegularGeometryCounts = System.Convert.FromBase64String( RegularGeometryCountsBase64 );
	public static readonly byte[] RegularTriangleIndices = System.Convert.FromBase64String( RegularTriangleIndicesBase64 );
	public static readonly ushort[] RegularVertexData = DecodeUShorts( RegularVertexDataBase64 );

	private static ushort[] DecodeUShorts( string base64 )
	{
		var bytes = System.Convert.FromBase64String( base64 );
		var values = new ushort[bytes.Length / sizeof( ushort )];
		System.Buffer.BlockCopy( bytes, 0, values, 0, bytes.Length );
		return values;
	}
}
